#!/usr/bin/env python3
"""Build a separate optional speed-consistent thermodynamic boundary control.

Usage: build_thermo_cpu.py --source PATH --name NAME
Original source files remain unchanged. Output is solver/thermo_cpu/NAME.cpp,
NAME.bin, NAME.diff and NAME_provenance.json. Relative quoted includes are
resolved against the original source directory using the compiler's-iquote.
"""
from pathlib import Path
import argparse,difflib,hashlib,json,re,subprocess,datetime
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'solver/thermo_cpu'
FIELDS=''' // Optional query-time ambient closure: coefficients use km/s and1AU density.
 bool speed_thermo_closure=false;
 double n_v2_cm3_kms2=0,T_over_v2_K_per_kms2=0;
'''
CONSTRUCTOR='''
  double closure_flag=c.d("boundary_speed_thermo_closure",0);
  if(!(closure_flag==0||closure_flag==1))throw std::runtime_error("boundary_speed_thermo_closure must be0 or1");
  speed_thermo_closure=closure_flag==1;
  n_v2_cm3_kms2=c.d("boundary_n_v2_cm3_kms2",0);
  T_over_v2_K_per_kms2=c.d("boundary_T_over_v2_K_per_kms2",0);
  if(speed_thermo_closure&&!(std::isfinite(n_v2_cm3_kms2)&&n_v2_cm3_kms2>0&&std::isfinite(T_over_v2_K_per_kms2)&&T_over_v2_K_per_kms2>0))
   throw std::runtime_error("Speed thermodynamic closure requires finite positive boundary_n_v2_cm3_kms2 and boundary_T_over_v2_K_per_kms2");
'''
ADJUST='''
  if(speed_thermo_closure){
   if(!(std::isfinite(z[0])&&z[0]>0))throw std::runtime_error("Speed thermodynamic closure requires finite positive adjusted speed");
   double v2=z[0]*z[0];z[1]=n_v2_cm3_kms2/v2;z[3]=T_over_v2_K_per_kms2*v2;
  }
'''
def extend(source):
 start=source.index('struct Boundary{');end=source.index('\nV er(',start)
 boundary=source[start:end]
 if 'boundary_speed_thermo_closure' in boundary:raise ValueError('Source already contains this closure')
 constructor=' explicit Boundary(const Config&c){'
 if boundary.count(constructor)!=1:raise ValueError('Cannot identify unique Boundary constructor')
 boundary=boundary.replace(constructor,FIELDS+constructor+CONSTRUCTOR,1)
 needle='z[0]+=speed_offset;'
 if boundary.count(needle)!=1:raise ValueError('Cannot identify unique speed-offset adjustment')
 boundary=boundary.replace(needle,needle+ADJUST,1)
 return source[:start]+boundary+source[end:]
def sha(data):return hashlib.sha256(data).hexdigest()
def main():
 parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--source',required=True,type=Path);parser.add_argument('--name',required=True);parser.add_argument('--cxx',default='g++');args=parser.parse_args()
 if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_-]{0,79}',args.name):parser.error('NAME must be a simple identifier')
 source=args.source.resolve();raw=source.read_bytes();text=raw.decode();generated=extend(text);OUT.mkdir(parents=True,exist_ok=True)
 target=OUT/(args.name+'.cpp');exe=OUT/(args.name+'.bin');target.write_text(generated)
 patch=''.join(difflib.unified_diff(text.splitlines(keepends=True),generated.splitlines(keepends=True),fromfile=str(source),tofile=str(target),n=4));(OUT/(args.name+'.diff')).write_text(patch)
 command=[args.cxx,'-O3','-std=c++17','-fopenmp','-iquote',str(source.parent),str(target),'-o',str(exe)]
 subprocess.run(command,check=True)
 if source.read_bytes()!=raw:raise RuntimeError('Original source changed during build')
 headers=[]
 for include in re.findall(r'^\s*#include\s+"([^"]+)"',text,re.MULTILINE):
  path=(source.parent/include).resolve()
  if path.exists():headers.append({'path':str(path),'sha256':sha(path.read_bytes())})
 record={'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'base_source':str(source),'base_sha256_before':sha(raw),'base_sha256_after':sha(source.read_bytes()),'generated_source':str(target),'generated_sha256':sha(target.read_bytes()),'executable':str(exe),'executable_sha256':sha(exe.read_bytes()),'diff_file':str(OUT/(args.name+'.diff')),'command':command,'quoted_headers':headers,'change_scope':'Only Boundary fields, constructor optional configuration and adjust after speed offset/before scaling. Cone application, all fluxes, integration and diagnostics unchanged.'}
 (OUT/(args.name+'_provenance.json')).write_text(json.dumps(record,indent=2)+'\n');print(json.dumps(record,indent=2))
